export const source = ":::exam-question\nid: ar1-t-p006-q01\ntitle: الكتاب · ص 4 · PDF 6 · السؤال 1\nquestion: ماذا رأى يوسف (عليه السلام)؟\nreference: الكتاب · ص 4 · PDF 6 · السؤال 1\nanswer-label: إجابة نموذجية للتدريب\nbody:\nماذا رأى يوسف (عليه السلام)؟\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nرأى أحد عشر كوكبًا والشمس والقمر ساجدين له.\nsolution:\nيقول الكتاب:\n\n> إِنِّي رَأَيْتُ **أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ** رَأَيْتُهُمْ لِي سَاجِدِينَ\n\nالمصدر: الرزمة التعليمية، ص 3 (PDF 5).\n:::\n\n:::exam-question\nid: ar1-t-p006-q02\ntitle: الكتاب · ص 4 · PDF 6 · السؤال 2\nquestion: مَن المقصود بالشمس والقمر في الآية الرابعة؟\nreference: الكتاب · ص 4 · PDF 6 · السؤال 2\nanswer-label: إجابة نموذجية للتدريب\nbody:\nمَن المقصود بالشمس والقمر في الآية الرابعة؟\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nأبوا يوسف عليه السلام.\nsolution:\nالمقصود بالشمس والقمر أبوا يوسف، والكواكب إخوته؛ فالرؤيا تعرض أفراد الأسرة في صورة أجرام سماوية.\n:::\n\n:::exam-question\nid: ar1-t-p006-q03\ntitle: الكتاب · ص 4 · PDF 6 · السؤال 3\nquestion: لماذا قال يعقوب لابنه يوسف (عليهما السلام): ﴿لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ﴾؟\nreference: الكتاب · ص 4 · PDF 6 · السؤال 3\nanswer-label: إجابة نموذجية للتدريب\nbody:\nلماذا قال يعقوب لابنه يوسف (عليهما السلام): ﴿لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ﴾؟\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nخشي أن يحسدوه ويكيدوا له إن عرفوا رؤياه.\nsolution:\nيقول الكتاب:\n\n> لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ **فَيَكِيدُوا لَكَ كَيْدًا**\n\nالمصدر: الرزمة التعليمية، ص 3 (PDF 5).\n:::\n\n:::exam-question\nid: ar1-t-p006-q04\ntitle: الكتاب · ص 4 · PDF 6 · السؤال 4\nquestion: ماذا أوحى الله - عز وجل - إلى يوسف عندما ألقاه إخوته في الجب؟\nreference: الكتاب · ص 4 · PDF 6 · السؤال 4\nanswer-label: إجابة نموذجية للتدريب\nbody:\nماذا أوحى الله - عز وجل - إلى يوسف عندما ألقاه إخوته في الجب؟\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nأوحى إليه أنه سيخبرهم مستقبلًا بما فعلوه به وهم لا يشعرون.\nsolution:\nيقول الكتاب:\n\n> وَأَوْحَيْنَا إِلَيْهِ **لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا** وَهُمْ لَا يَشْعُرُونَ\n\nالمصدر: الرزمة التعليمية، ص 3 (PDF 5).\n:::\n\n:::exam-question\nid: ar1-t-p006-q05\ntitle: الكتاب · ص 4 · PDF 6 · السؤال 5\nquestion: نذكر الآراء المختلفة التي طرحها إخوة يوسف للتخلص منه.\nreference: الكتاب · ص 4 · PDF 6 · السؤال 5\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنذكر الآراء المختلفة التي طرحها إخوة يوسف للتخلص منه.\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nاقترحوا قتله، أو طرحه في أرض بعيدة، أو إلقاءه في غيابة الجب ليلتقطه بعض السيّارة.\nsolution:\nتظهر ثلاثة مقترحات في الآيتين التاسعة والعاشرة: القتل، والإبعاد في أرض، والإلقاء في الجبّ ليلتقطه المسافرون. وهي بدائل اقترحها الإخوة قبل اتفاقهم على الجبّ.\n:::\n\n:::exam-question\nid: ar1-t-p006-q06\ntitle: الكتاب · ص 4 · PDF 6 · السؤال 6\nquestion: نبين العقوبة التي اقترحت امرأة العزيز إيقاعها بيوسف (عليه السلام).\nreference: الكتاب · ص 4 · PDF 6 · السؤال 6\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنبين العقوبة التي اقترحت امرأة العزيز إيقاعها بيوسف (عليه السلام).\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nاقترحت سجنه أو إيقاع عذاب أليم به.\nsolution:\nيقول الكتاب:\n\n> مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا **أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ**\n\nالمصدر: الرزمة التعليمية، ص 4 (PDF 6).\n:::\n\n:::exam-question\nid: ar1-t-p006-q07\ntitle: الكتاب · ص 4 · PDF 6 · السؤال 7\nquestion: ما الأقوال والأفعال التي نُسبت في الآيات لامرأة العزيز؟\nreference: الكتاب · ص 4 · PDF 6 · السؤال 7\nanswer-label: إجابة نموذجية للتدريب\nbody:\nما الأقوال والأفعال التي نُسبت في الآيات لامرأة العزيز؟\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nراودته عن نفسه وغلّقت الأبواب وقالت «هيت لك». واستبقت معه الباب وقدّت قميصه من دبر، ثم اتهمته أمام زوجها واقترحت سجنه أو تعذيبه.\nsolution:\nنرتّب ما نُسب إليها بحسب الحادثة: المراودة وإغلاق الأبواب، ثم الدعوة «هيت لك»، ثم ملاحقة يوسف وشقّ قميصه، ثم اتهامه واقتراح عقوبته. هذا الترتيب يميز أقوالها المباشرة من أفعالها.\n:::\n\n:::exam-question\nid: ar1-t-p006-q08\ntitle: الكتاب · ص 4 · PDF 6 · السؤال 8\nquestion: نوضح المقصود بقوله تعالى: ﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا﴾.\nreference: الكتاب · ص 4 · PDF 6 · السؤال 8\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنوضح المقصود بقوله تعالى: ﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا﴾.\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nاترك الحديث عمّا حدث ولا تُفشه.\nsolution:\n«أعرض» في هذا المقام بمعنى اترك الحديث عن الحادثة واكتمها؛ فالخطاب جاء بعد انكشاف الحقيقة أمام العزيز، وليس أمرًا بإنكارها.\n:::\n\n:::exam-question\nid: ar1-t-p007-q01\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 1\nquestion: قال تعالى على لسان إخوة يوسف: ﴿فَأَكَلَهُ الذِّئْبُ﴾، وكانوا كاذبين، ما الدليل على كذبهم؟\nreference: الكتاب · ص 5 · PDF 7 · السؤال 1\nanswer-label: إجابة نموذجية للتدريب\nbody:\nقال تعالى على لسان إخوة يوسف: ﴿فَأَكَلَهُ الذِّئْبُ﴾، وكانوا كاذبين، ما الدليل على كذبهم؟\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nجاؤوا على قميصه بدم كذب ولم يتمزّق القميص كما يُتوقّع لو افترسه الذئب. وتبيّن الآيات أنهم ألقوه في الجب والتقطته السيّارة حيًّا.\nsolution:\nالرواية تزعم افتراس الذئب ليوسف، والافتراس يُتوقّع معه تمزّق الثوب. سلامة القميص مع وجود الدم تكشف اصطناع القرينة، ويؤكد السياق أن يوسف كان حيًّا حين التقطته القافلة.\n:::\n\n:::exam-question\nid: ar1-t-p007-q02\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 2\nquestion: ما دلالة قدّ القميص من قُبُل أو دُبُر؟\nreference: الكتاب · ص 5 · PDF 7 · السؤال 2\nanswer-label: إجابة نموذجية للتدريب\nbody:\nما دلالة قدّ القميص من قُبُل أو دُبُر؟\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nالقدّ من قُبُل يوافق دعوى المرأة ويُكذّب يوسف، والقدّ من دُبُر يدل على فراره منها فيصدّقه ويُكذّبها.\nsolution:\nلو كان يوسف مهاجمًا والمرأة تدفعه لشُقّ القميص من الأمام. أمّا شقّه من الخلف فيوافق فراره وهي تلحقه وتمسك قميصه؛ لذلك صار القدّ من دبر دليلًا على صدقه وكذب دعواها.\n:::\n\n:::exam-question\nid: ar1-t-p007-q03\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 3\nquestion: لماذا وصف الله - عز وجل - القصة بأنها أحسن القصص؟\nreference: الكتاب · ص 5 · PDF 7 · السؤال 3\nanswer-label: إجابة نموذجية للتدريب\nbody:\nلماذا وصف الله - عز وجل - القصة بأنها أحسن القصص؟\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nلما فيها من العبر، مثل عاقبة الصبر والعفة، وحسن عرض الأحداث وترابطها.\nsolution:\nتتكامل أحداث القصة من الرؤيا إلى تحققها، وتعرض صراع الحسد والعفة والصبر ونتائجه. اجتماع وحدة البناء مع العبرة الأخلاقية يفسّر وصفها بأحسن القصص.\n:::\n\n:::exam-question\nid: ar1-t-p007-q04\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 4\nquestion: في الآيات ما يوضح أن يوسف من عباد الله المخلصين، نبيّن ذلك.\nreference: الكتاب · ص 5 · PDF 7 · السؤال 4\nanswer-label: إجابة نموذجية للتدريب\nbody:\nفي الآيات ما يوضح أن يوسف من عباد الله المخلصين، نبيّن ذلك.\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nاستعاذ بالله وامتنع عن الاستجابة للمراودة، ونصّت الآية على إخلاصه: ﴿إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ﴾.\nsolution:\nنقرأ موقفه عند المراودة: استعاذ بالله ورفض خيانة من أحسن إليه؛ ثم جاء وصفه «إنه من عبادنا المخلصين». فالدليل يجمع سلوكه العملي وشهادة النص له بالإخلاص.\n:::\n\n:::exam-question\nid: ar1-t-p007-q05\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 5\nquestion: ما الحكمة من تنكير كلمة (شاهد)؟\nreference: الكتاب · ص 5 · PDF 7 · السؤال 5\nanswer-label: إجابة نموذجية للتدريب\nbody:\nما الحكمة من تنكير كلمة (شاهد)؟\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nلأن العبرة بالشهادة ودليلها، لا باسم الشاهد. وكونه من أهلها يقوّي الحجّة عليها.\nsolution:\nلم يُذكر اسم الشاهد؛ لأن قيمة شهادته في البرهان الذي عرضه: موضع شقّ القميص. وكونه من أهل المرأة يجعل الحكم أبعد عن اتهامه بمحاباة يوسف.\n:::\n\n:::exam-question\nid: ar1-t-p007-q06\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 6\nquestion: الحسد آفة اجتماعية، نناقش أثر هذه الظاهرة.\nreference: الكتاب · ص 5 · PDF 7 · السؤال 6\nanswer-label: إجابة نموذجية للتدريب\nbody:\nالحسد آفة اجتماعية، نناقش أثر هذه الظاهرة.\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nالحسد يُفسد المودّة وقد يدفع إلى الظلم كما فعل إخوة يوسف. ويُواجَه بتمنّي الخير للآخرين، وطلب الفضل من الله، وتجنّب المقارنة المؤذية.\nsolution:\nيظهر ضرر الحسد حين تتحول الغيرة إلى رغبة في إقصاء صاحب النعمة وإيذائه؛ وهذا ما حدث حين خطط الإخوة للتخلص من يوسف. تُناقش الظاهرة بربط الشعور بسلوكه ونتيجته، ثم تقديم بديل يحفظ المحبة ويمنع الظلم.\n:::\n\n:::exam-question\nid: ar1-t-p007-q07\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 7\nquestion: ظهرت بعض عناصر القصة جلية في الآيات الكريمة، نذكرها.\nreference: الكتاب · ص 5 · PDF 7 · السؤال 7\nanswer-label: إجابة نموذجية للتدريب\nbody:\nظهرت بعض عناصر القصة جلية في الآيات الكريمة، نذكرها.\n\n### نص الدرس: اشتدي أزمة تنفرجي\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝١﴾\n\n﴿إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝٢﴾\n\n﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣﴾\n\n﴿إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤﴾\n\n﴿قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾\n\n﴿وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧﴾\n\n﴿إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨﴾\n\n﴿اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩﴾\n\n﴿قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠﴾\n\n﴿قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾\n\n﴿أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحَافِظُونَ ۝١٢﴾\n\n﴿قَالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخَافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غَافِلُونَ ۝١٣﴾\n\n﴿قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَخَاسِرُونَ ۝١٤﴾\n\n﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَتِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥﴾\n\n﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦﴾\n\n﴿قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ ۝١٧﴾\n\n﴿وَجَاءُوا عَلَىٰ قَمِيصِهِ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨﴾\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝١٩﴾\n\n﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠﴾\n\n﴿وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾\n\n﴿وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ ۝٢٢﴾\n\n﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ ۝٢٣﴾\n\n﴿وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ ۝٢٤﴾\n\n﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥﴾\n\n﴿قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦﴾\n\n﴿وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧﴾\n\n﴿فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ ۝٢٨﴾\n\n﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾\n\nالنص من الكتاب، ص 3–4\nfinal-answer:\nالشخصيات مثل يوسف ويعقوب والإخوة وامرأة العزيز، والأحداث مثل الرؤيا والجب والمراودة، والحوار، والمكان مثل الجب وبيت العزيز، والعقدة والحل في حادثة القميص.\nsolution:\nنربط كل عنصر بشاهد: يوسف وإخوته شخصيات؛ والجبّ وبيت العزيز مكانان؛ والرؤيا والإلقاء والمراودة أحداث؛ وأقوال الشخصيات حوار. وفي حادثة القميص تظهر عقدة الاتهام ثم حلّها بالقرينة المادية.\n:::\n\n:::mcq\nid: ar1-t-p007-q08\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 1-أ\nkicker: الكتاب · ص 5 · PDF 7 · السؤال 1-أ\nreference: الكتاب · ص 5 · PDF 7 · السؤال 1-أ\nquestion: ما المعنى المستفاد من الزيادة في قوله تعالى: «وغلّقت»؟\n- [ ] option-1 | التدرج.\n- [x] option-2 | المبالغة.\n- [ ] option-3 | التعدية.\n- [ ] option-4 | السلب.\nexplanation:\n«غلّق» على وزن «فعّل» بتضعيف اللام، وتفيد الزيادة هنا المبالغة في إحكام إغلاق الأبواب. يُحدّد السياق معنى الزيادة؛ فلا يُختار التدرّج أو التعدية لمجرد وجود حرف زائد.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-t-p007-q09\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 1-ب\nkicker: الكتاب · ص 5 · PDF 7 · السؤال 1-ب\nreference: الكتاب · ص 5 · PDF 7 · السؤال 1-ب\nquestion: ما الأسلوب الوارد في قوله تعالى: ﴿وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ﴾؟\n- [ ] option-1 | قسم.\n- [ ] option-2 | استفهام.\n- [x] option-3 | شرط.\n- [ ] option-4 | تعجب.\nexplanation:\nتربط «لولا» النتيجة بوجود المانع: رؤية البرهان حالت دون الوقوع في الفتنة. فهي أداة شرط غير جازمة تفيد الامتناع لوجود، ولذلك فالأسلوب شرط.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-t-p007-q10\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 1-ج\nkicker: الكتاب · ص 5 · PDF 7 · السؤال 1-ج\nreference: الكتاب · ص 5 · PDF 7 · السؤال 1-ج\nquestion: ما إعراب كلمة (كوكبًا) في قوله تعالى: ﴿إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا﴾؟\n- [ ] option-1 | مفعول به ثانٍ.\n- [x] option-2 | تمييز.\n- [ ] option-3 | مفعول مطلق.\n- [ ] option-4 | نعت.\nexplanation:\n«أحد عشر» عدد، و«كوكبًا» يبيّن المقصود به ويزيل إبهامه؛ لذا يُعرب تمييزًا مفردًا منصوبًا بالفتحة. لم يُطلب به مفعول آخر للفعل «رأيت».\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::exam-question\nid: ar1-t-p007-q11\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 2\nquestion: ما الأصل اللغوي لكلمة (المستعان)؟\nreference: الكتاب · ص 5 · PDF 7 · السؤال 2\nanswer-label: إجابة نموذجية للتدريب\nbody:\nما الأصل اللغوي لكلمة (المستعان)؟\nfinal-answer:\nع و ن.\nsolution:\n«المستعان» مشتق من «استعان» بمعنى طلب العون. نردّ المزيد إلى مادته «عَوْن»، فنحصل على الجذر ع و ن، مع ملاحظة أن الألف في المشتق ناتجة عن إعلال الواو.\n:::\n\n:::exam-question\nid: ar1-t-p007-q12\ntitle: الكتاب · ص 5 · PDF 7 · السؤال 3\nquestion: ما علامة إعراب (أبويك) في قوله تعالى: ﴿وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ ۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ﴾؟\nreference: الكتاب · ص 5 · PDF 7 · السؤال 3\nanswer-label: إجابة نموذجية للتدريب\nbody:\nما علامة إعراب (أبويك) في قوله تعالى: ﴿وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ ۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ﴾؟\nfinal-answer:\nالياء؛ لأنه مثنّى مجرور بـ«على».\nsolution:\nدخل حرف الجر «على» على «أبويك»، فالكلمة مجرورة. وهي مثنّى «أب» أُضيف إلى الضمير وحُذفت نونه؛ وعلامة جر المثنّى الياء. لا تُعرب هنا بعلامة الأسماء الخمسة؛ لأنها مثنّى.\n:::\n\n:::mcq\nid: ar1-t-p026-q01\ntitle: الكتاب · ص 24 · PDF 26 · السؤال 1-1\nkicker: الكتاب · ص 24 · PDF 26 · السؤال 1-1\nreference: الكتاب · ص 24 · PDF 26 · السؤال 1-1\nquestion: ما المعنى المستفاد من الزيادة في (وغلّقت) من قوله تعالى: ﴿وَغَلَّقَتِ الْأَبْوَابَ﴾؟\n- [ ] option-1 | التدرج.\n- [ ] option-2 | التعدية.\n- [x] option-3 | المبالغة.\n- [ ] option-4 | الطلب.\nexplanation:\nأصل الفعل «غَلَقَ»، وزيادة التضعيف في «غَلَّقَ» تدلّ هنا على **المبالغة في الإغلاق وإحكامه**. فالسياق يصوّر إغلاق الأبواب إغلاقًا شديدًا، ولا يطلب وقوع الفعل كما تفيد صيغة الطلب.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-t-p026-q03\ntitle: الكتاب · ص 24 · PDF 26 · السؤال 1-3\nkicker: الكتاب · ص 24 · PDF 26 · السؤال 1-3\nreference: الكتاب · ص 24 · PDF 26 · السؤال 1-3\nquestion: نوع الواو في قوله تعالى ﴿وَنَحْنُ عُصْبَةٌ﴾ هو:\n- [x] option-1 | حالية.\n- [ ] option-2 | استئنافية.\n- [ ] option-3 | عاطفة.\n- [ ] option-4 | معيّة.\nexplanation:\nالجملة الاسمية «نحن عصبة» تصف حال إخوة يوسف عند موازنتهم أنفسهم بأخيهم: كيف يفضّل أبونا يوسف ونحن جماعة قوية؟ يصحّ تقدير «والحال أننا عصبة»، فتكون الواو **واو الحال**، والجملة بعدها في محل نصب حال.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-t-p026-q06\ntitle: الكتاب · ص 24 · PDF 26 · السؤال 1-6\nkicker: الكتاب · ص 24 · PDF 26 · السؤال 1-6\nreference: الكتاب · ص 24 · PDF 26 · السؤال 1-6\nquestion: ما المعنى الذي يفيده حرف الجر (من) في قوله تعالى: ﴿وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ﴾؟\n- [ ] option-1 | زائدة للتوكيد.\n- [x] option-2 | التبعيض.\n- [ ] option-3 | الاستعانة.\n- [ ] option-4 | ابتداء الغاية.\nexplanation:\nالتعليم هنا واقع على بعض علم تأويل الأحاديث، فيصحّ تقدير المعنى: يعلّمك بعض تأويل الأحاديث. لذا تفيد «مِن» **التبعيض**؛ ولا يصوّر السياق استعانةً بشيء أو بداية مكانية.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-t-p027-q01\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 2-1\nkicker: الكتاب · ص 25 · PDF 27 · السؤال 2-1\nreference: الكتاب · ص 25 · PDF 27 · السؤال 2-1\nquestion: ما المحسن البديعي في اللفظتين: (شروه، واشتراه)؟\n- [ ] option-1 | ترادف.\n- [ ] option-2 | جناس.\n- [x] option-3 | طباق.\n- [ ] option-4 | مقابلة.\nexplanation:\n«شَرَوْه» في سياق قصة يوسف تعني **باعوه**، وتقابلها «اشتراه» بمعنى ابتاعه. اجتماع البيع والشراء، وهما معنيان متضادان، يكوّن **طباقًا**؛ فالعبرة بالمعنى في السياق، لا بتشابه الحروف.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n**نص السؤال 2**\n\nنقرأ النص الآتي، ثم نجيب عمّا يليه:\n\nقال تعالى: ﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠ وَقَالَ الَّذِي اشْتَرَاهُ مِنْ <u>مِصْرَ</u> لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا <u>لِيُوسُفَ</u> فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ <u>الْأَحَادِيثِ</u> وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾.\n:::\n\n:::mcq\nid: ar1-t-p027-q02\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 2-2\nkicker: الكتاب · ص 25 · PDF 27 · السؤال 2-2\nreference: الكتاب · ص 25 · PDF 27 · السؤال 2-2\nquestion: ما الأسلوب الوارد في قوله تعالى: ﴿وَهَمَّ بِهَا لَوْلَا أَنْ رَأَىٰ بُرْهَانَ رَبِّهِ﴾؟\n- [ ] option-1 | قسم.\n- [ ] option-2 | تعجّب.\n- [x] option-3 | شرط.\n- [ ] option-4 | استفهام.\nexplanation:\n«لولا» تربط امتناع أمر بوجود غيره؛ فرؤية يوسف برهان ربّه حالت دون وقوع المحظور. هذا الربط الشرطي يجعل الأسلوب **شرطًا** بـ«لولا»، وهي حرف امتناع لوجود، وليس استفهامًا أو قسمًا.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n**نص السؤال 2**\n\nنقرأ النص الآتي، ثم نجيب عمّا يليه:\n\nقال تعالى: ﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠ وَقَالَ الَّذِي اشْتَرَاهُ مِنْ <u>مِصْرَ</u> لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا <u>لِيُوسُفَ</u> فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ <u>الْأَحَادِيثِ</u> وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾.\n:::\n\n:::exam-question\nid: ar1-t-p027-q03\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 2-3\nquestion: كيف مكّن الله ليوسف في الأرض؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 2-3\nanswer-label: إجابة نموذجية للتدريب\nbody:\nكيف مكّن الله ليوسف في الأرض؟\n\n**نص السؤال 2**\n\nنقرأ النص الآتي، ثم نجيب عمّا يليه:\n\nقال تعالى: ﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠ وَقَالَ الَّذِي اشْتَرَاهُ مِنْ <u>مِصْرَ</u> لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا <u>لِيُوسُفَ</u> فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ <u>الْأَحَادِيثِ</u> وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾.\nfinal-answer:\nأنجاه من الجب، ويسّر له أن يشتريه عزيز مصر ويحسن مثواه، وعلّمه من تأويل الأحاديث.\nsolution:\nيُفهم التمكين بتتبّع انتقال يوسف من الشدّة إلى أسباب الاستقرار والعلم: **نجا من الجب، ثم اشتراه عزيز مصر وأوصى بإكرام مثواه، وعلّمه الله من تأويل الأحاديث**. هذه الأحداث توضّح كيف هيّأ الله له مكانًا في الأرض بعد محنته.\n:::\n\n:::exam-question\nid: ar1-t-p027-q04\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 2-4\nquestion: ما المقصود بقوله تعالى: ﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا﴾؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 2-4\nanswer-label: إجابة نموذجية للتدريب\nbody:\nما المقصود بقوله تعالى: ﴿يُوسُفُ أَعْرِضْ عَنْ هَٰذَا﴾؟\n\n**نص السؤال 2**\n\nنقرأ النص الآتي، ثم نجيب عمّا يليه:\n\nقال تعالى: ﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠ وَقَالَ الَّذِي اشْتَرَاهُ مِنْ <u>مِصْرَ</u> لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا <u>لِيُوسُفَ</u> فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ <u>الْأَحَادِيثِ</u> وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾.\nfinal-answer:\nأعرض عن ذكر ما حدث ولا تُفشه.\nsolution:\nالفعل «أعرض» في هذا السياق طلب لترك الحديث عن الحادثة وكتمانها؛ فالمقصود: **لا تذكر ما حدث ولا تُفشه**، لا الإعراض عن أداء واجب أو ترك المكان.\n:::\n\n:::exam-question\nid: ar1-t-p027-q05\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 2-5\nquestion: نستخرج من النص: بدلًا، وفعلًا متعديًا لمفعولين، واسمًا مقصورًا، وخبرًا لفعل ناسخ.\nreference: الكتاب · ص 25 · PDF 27 · السؤال 2-5\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنستخرج من النص: بدلًا، وفعلًا متعديًا لمفعولين، واسمًا مقصورًا، وخبرًا لفعل ناسخ.\n\n**نص السؤال 2**\n\nنقرأ النص الآتي، ثم نجيب عمّا يليه:\n\nقال تعالى: ﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠ وَقَالَ الَّذِي اشْتَرَاهُ مِنْ <u>مِصْرَ</u> لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا <u>لِيُوسُفَ</u> فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ <u>الْأَحَادِيثِ</u> وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾.\nfinal-answer:\nالبدل: «دراهمَ» بدل من «ثمنٍ». الفعل المتعدّي لمفعولين: «نتّخذ» (الهاء، ولدًا). الاسم المقصور: «مثواه». خبر الفعل الناسخ: «من الزاهدين» خبر كانوا في محل نصب.\nsolution:\n- **«دراهمَ» بدل من «ثمنٍ»:** بيّنت نوع الثمن الذي بيع به يوسف، وهي مجرورة تبعًا للمبدل منه، وعلامة جرّها الفتحة لأنها صيغة منتهى الجموع مجردة من «أل» والإضافة.\n- **«نتّخذ» فعل متعدٍّ لمفعولين:** في «نتّخذه ولدًا» الهاء مفعول به أول، و«ولدًا» مفعول به ثانٍ.\n- **«مثواه» اسم مقصور:** آخره ألف لازمة قبل اتصال الهاء، وهي في «مثوى».\n- **«من الزاهدين» خبر «كانوا»:** الواو اسم «كان»، وشبه الجملة يتمّم معناها، فهو في محل نصب خبرها.\n:::\n\n:::exam-question\nid: ar1-t-p027-q06\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 2-6\nquestion: الكلمات: (شروه، الزاهدين، تأويل)، ما مرادف الأولى؟ وما المعنى الصرفي للثانية؟ وما المادة المعجمية للثالثة؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 2-6\nanswer-label: إجابة نموذجية للتدريب\nbody:\nالكلمات: (شروه، الزاهدين، تأويل)، ما مرادف الأولى؟ وما المعنى الصرفي للثانية؟ وما المادة المعجمية للثالثة؟\n\n**نص السؤال 2**\n\nنقرأ النص الآتي، ثم نجيب عمّا يليه:\n\nقال تعالى: ﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠ وَقَالَ الَّذِي اشْتَرَاهُ مِنْ <u>مِصْرَ</u> لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا <u>لِيُوسُفَ</u> فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ <u>الْأَحَادِيثِ</u> وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾.\nfinal-answer:\nشروه: باعوه. الزاهدين: جمع مذكر سالم لاسم الفاعل «زاهد». تأويل: أ و ل.\nsolution:\n- **«شروه» تعني باعوه:** يحدّد سياق دفع الثمن وشراء العزيز هذا المعنى.\n- **«الزاهدين» جمع مذكّر سالم لاسم الفاعل «زاهد»:** مفرده على وزن «فاعل»، ويدلّ على من اتّصف بالزهد.\n- **مادة «تأويل» هي «أ و ل»:** نردّ المصدر إلى أصله «أوّل»، فتبقى الهمزة والواو واللام أصول الكلمة.\n:::\n\n:::exam-question\nid: ar1-t-p027-q07\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 2-7\nquestion: لِمَ سُمّيت القصة أحسن القصص كما في قوله تعالى: ﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ﴾؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 2-7\nanswer-label: إجابة نموذجية للتدريب\nbody:\nلِمَ سُمّيت القصة أحسن القصص كما في قوله تعالى: ﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ﴾؟\n\n**نص السؤال 2**\n\nنقرأ النص الآتي، ثم نجيب عمّا يليه:\n\nقال تعالى: ﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠ وَقَالَ الَّذِي اشْتَرَاهُ مِنْ <u>مِصْرَ</u> لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا <u>لِيُوسُفَ</u> فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ <u>الْأَحَادِيثِ</u> وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾.\nfinal-answer:\nلحسن عرضها، وما تجمعه من العبر، ومنها الصبر والعفّة وحسن العاقبة.\nsolution:\nتتضمّن القصة محنًا متتابعة يصبر يوسف عليها ويحافظ خلالها على عفّته، ثم يظهر حسن عاقبته. ويجتمع هذا المعنى التربوي مع ترابط الأحداث وحسن عرضها؛ لذلك كان وجه تسميتها **أحسن القصص** حسن بنائها وما تحمله من عبر، ومنها الصبر والعفّة.\n:::\n\n:::exam-question\nid: ar1-t-p027-q08\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 2-8\nquestion: نعرب ما تحته خطّ.\nreference: الكتاب · ص 25 · PDF 27 · السؤال 2-8\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنعرب ما تحته خطّ.\n\n**نص السؤال 2**\n\nنقرأ النص الآتي، ثم نجيب عمّا يليه:\n\nقال تعالى: ﴿وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝٢٠ وَقَالَ الَّذِي اشْتَرَاهُ مِنْ <u>مِصْرَ</u> لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا <u>لِيُوسُفَ</u> فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ <u>الْأَحَادِيثِ</u> وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ ۝٢١﴾.\nfinal-answer:\nمصرَ: اسم مجرور بـ«من» وعلامة جرّه الفتحة نيابةً عن الكسرة. ليوسفَ: اللام حرف جر، ويوسف اسم مجرور بالفتحة نيابةً عن الكسرة. الأحاديثِ: مضاف إليه مجرور بالكسرة.\nsolution:\n- **«مصرَ»:** سبقتها «من»، فهي اسم مجرور. جاءت الفتحة نيابة عن الكسرة على منع العلم من الصرف باعتباره اسم بلد مؤنثًا؛ مع ملاحظة أن الثلاثي ساكن الوسط من هذا النوع يجوز صرفه ومنعه.\n- **«ليوسفَ»:** اللام حرف جر، و«يوسف» اسم مجرور بالفتحة نيابة عن الكسرة؛ لأنه علم أعجمي زائد على ثلاثة أحرف، مجرد من «أل» والإضافة.\n- **«الأحاديثِ»:** أضيف «تأويل» إليها، فهي مضاف إليه مجرور بالكسرة الظاهرة. وهي معرّفة بـ«أل»، فلا تُجرّ بالفتحة هنا.\n:::\n\n:::mcq\nid: ar1-e-p006-q01\ntitle: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 1 · 2019\nkicker: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 1 · 2019\nreference: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 1 · 2019\nquestion: ما معنى (يرتع) في قوله تعالى: «أرسله معنا غدًا يرتع ويلعب»؟\n- [ ] option-1 | يسبح.\n- [ ] option-2 | يتسابق.\n- [x] option-3 | يأكل.\n- [ ] option-4 | يعمل.\nexplanation:\n«يرتع» هنا بمعنى يأكل ويتنعّم في المرعى؛ فالإخوة يطلبون اصطحاب يوسف للتنزّه، وتؤكد «ويلعب» هذا السياق.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p006-q02\ntitle: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 2 · 2020\nkicker: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 2 · 2020\nreference: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 2 · 2020\nquestion: مَن المقصود بـ(الأبوين) في قوله تعالى في سورة يوسف: ﴿كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ﴾ (يوسف: ٦)؟\n- [ ] option-1 | إسحق ويعقوب.\n- [ ] option-2 | آدم ويعقوب.\n- [x] option-3 | إبراهيم وإسحق.\n- [ ] option-4 | آدم وإبراهيم.\nexplanation:\nتذكر الآية الاسمين بعد «أبويك» مباشرةً: إبراهيم وإسحاق. فالمقصود بالأبوين هنا الجدّان، ويُستدل بالتفسير الوارد في الآية نفسها لا بمعنى الأب المباشر وحده.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p006-q03\ntitle: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 3 · 2020\nkicker: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 3 · 2020\nreference: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 3 · 2020\nquestion: ما المقصود بكلمة (السيارة) في قوله تعالى: «وجاءت سيارة فأرسلوا واردهم»؟\n- [ ] option-1 | المركبة الآلية.\n- [ ] option-2 | الكواكب.\n- [x] option-3 | القافلة.\n- [ ] option-4 | امرأة عجلى.\nexplanation:\nيقول الكتاب:\n\n> كلمة السّيّارة تعني **القافلة**، وصارت تستخدم بعد ذلك صفة للكواكب المعروفة (عطارد، والمرّيخ، وزُحل...)، وهي تستخدم اليوم بمعنى المركبة الّتي نستقلّها في تنقّلنا من مكان إلى آخر.\n\nالمصدر: الرزمة التعليمية، ص 4 (PDF 6).\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p006-q04\ntitle: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 4 · 2020\nkicker: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 4 · 2020\nreference: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 4 · 2020\nquestion: ما المعنى المستفاد من الزيادة في قوله تعالى: «وغلّقت»؟\n- [ ] option-1 | التعدية.\n- [ ] option-2 | التدرج.\n- [x] option-3 | المبالغة.\n- [ ] option-4 | السلب.\nexplanation:\nالفعل «غلّقت» مزيد بتضعيف العين على وزن «فعّل»، بينما أصل المعنى في «أغلقت». يدلّ التضعيف هنا على المبالغة في إحكام إغلاق الأبواب، لا على سلب الإغلاق أو تدرّجه.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p006-q05\ntitle: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 5 · 2020\nkicker: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 5 · 2020\nreference: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 5 · 2020\nquestion: ما الدليل على كذب إخوة يوسف -عليه السلام- في قوله تعالى: «وجاءوا على قميصه بدم كذب»؟\n- [x] option-1 | عدم تمزق القميص رغم ادعائهم أن الذئب أكله.\n- [ ] option-2 | أنّ القميص قُدّ من دبر وليس من قُبُل.\n- [ ] option-3 | لم يكن القميص ليوسف عليه السلام.\n- [ ] option-4 | كانت رواياتهم للحديث مختلفة.\nexplanation:\nلو افترس الذئب يوسف لتمزّق قميصه مع افتراس جسمه، لكن الإخوة جاءوا بالقميص سليمًا وعليه الدم؛ فتعارضت القرينة المادية مع روايتهم. أمّا شقّه من دبر فقرينة في حادثة امرأة العزيز، وهي حادثة أخرى.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p006-q06\ntitle: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 6 · 2021\nkicker: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 6 · 2021\nreference: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 6 · 2021\nquestion: ما الأسلوب اللغوي الوارد في قوله تعالى: «وهمّ بها لولا أن رأى برهان ربه»؟\n- [ ] option-1 | قسم.\n- [ ] option-2 | تعجب.\n- [ ] option-3 | استفهام.\n- [x] option-4 | شرط.\nexplanation:\n«لولا» أداة شرط غير جازمة تفيد امتناع أمر لوجود غيره؛ فوجود برهان الربّ مانع من الاستجابة للفتنة. لذلك يُصنّف التركيب ضمن الشرط، وليس استفهامًا أو قسمًا.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p006-q07\ntitle: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 7 · 2021\nkicker: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 7 · 2021\nreference: مجموعة الامتحانات · ص 5 · PDF 6 · السؤال 7 · 2021\nquestion: ما الأقوال التي نُسبت في سورة يوسف لامرأة العزيز؟\n- [ ] option-1 | همّت به.\n- [ ] option-2 | غلّقت الأبواب.\n- [x] option-3 | هيت لك.\n- [ ] option-4 | قدّت قميصه.\nexplanation:\nنميّز القول من الفعل: «هيت لك» كلام نطقت به المرأة تدعو به يوسف إلى الإقبال، أمّا إغلاق الأبواب وقدّ القميص والهمّ فهي أفعال أو أحوال.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::exam-question\nid: ar1-e-p007-q01\ntitle: مجموعة الامتحانات · ص 6 · PDF 7 · السؤال 1 · 2019، الدورة الأولى، شهر 6\nquestion: اقرأ الآيات الكريمة الآتية من سورة يوسف، ثمّ أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 6 · PDF 7 · السؤال 1 · 2019، الدورة الأولى، شهر 6\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الآيات الكريمة الآتية من سورة يوسف، ثمّ أجب عن الأسئلة التي تليها:\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝ إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ <u>عُصْبَةٌ</u> إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝ اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝ قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَةِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ <u>السَّيَّارَةِ</u> إِنْ كُنْتُمْ فَاعِلِينَ﴾.\n\n- أ. ما معنى ما تحته خط: (عصبة، السيارة)؟\n- ب. اذكر مقترحين طرحهما إخوة يوسف -عليه السلام- للتخلص منه.\n- ج. ما نوع اللام في (ليوسف وأخوه)؟\nfinal-answer:\n- أ. عصبة: جماعة (ما زاد العدد عن عشرة وأكثر). السيارة: القافلة، أو المارّة من المسافرين.\n- ب. أن يقتلوا يوسف، أن يلقوه في مكان بعيد، أن يلقوه في الجبّ.\n- ج. لام الابتداء.\nsolution:\nمعنى «عصبة» جماعة متماسكة، و«السيّارة» قافلة المسافرين. وتظهر مقترحات الإخوة في الأفعال: «اقتلوا»، «اطرحوه»، «ألقوه»؛ ويكفي ذكر اثنين مما طلبه السؤال. واللام في «ليوسف» لام ابتداء دخلت على المبتدأ لتوكيد الحكم، ولم تجرّه.\n:::\n\n:::exam-question\nid: ar1-e-p007-q02\ntitle: مجموعة الامتحانات · ص 6 · PDF 7 · السؤال 2 · 2019، الدورة الثالثة، 2019/12/7\nquestion: اقرأ الآيات الكريمة الآتية من سورة يوسف، ثم أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 6 · PDF 7 · السؤال 2 · 2019، الدورة الثالثة، 2019/12/7\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الآيات الكريمة الآتية من سورة يوسف، ثم أجب عن الأسئلة التي تليها:\n\n﴿الر تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ ۝ إِنَّا أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ ۝ نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝ إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝ قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝ وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ ۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ﴾.\n\n- أ. وردت في الآيات الكلمتان: (يجتبيك، كوكبًا). ما معنى الأولى؟ وما إعراب الثانية؟\n- ب. مَن المخاطب في قوله تعالى: «وإن كنت من قبله لمن الغافلين»؟\n- ج. لماذا قال يعقوب لابنه يوسف -عليهما السلام-: «لا تقصص رؤياك على إخوتك»؟\nfinal-answer:\n- أ. الأولى: يجتبيك: يصطفيك، يختارك. الثانية: كوكبًا: تمييز منصوب وعلامة نصبه الفتحة الظاهرة على آخره.\n- ب. المخاطب: سيّدنا محمد ﷺ.\n- ج. كي لا يكيدوا له حسدًا وغيرة.\nsolution:\n«يجتبيك» بمعنى يختارك ويصطفيك. و«كوكبًا» ترفع إبهام العدد «أحد عشر»، لذا هي تمييز مفرد منصوب. والخطاب عن الوحي بـ«هذا القرآن» موجّه إلى محمد ﷺ. ويربط قوله «فيكيدوا لك كيدًا» النهيَ عن قصّ الرؤيا بخوف يعقوب من حسد إخوة يوسف له.\n:::\n\n:::exam-question\nid: ar1-e-p007-q03\ntitle: مجموعة الامتحانات · ص 6 · PDF 7 · السؤال 3 · 2020، الدورة الثانية، شهر 8\nquestion: اقرأ الآيات الكريمة الآتية من سورة يوسف، ثم أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 6 · PDF 7 · السؤال 3 · 2020، الدورة الثانية، شهر 8\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الآيات الكريمة الآتية من سورة يوسف، ثم أجب عن الأسئلة التي تليها:\n\n﴿وَجَاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُ قَالَ يَا بُشْرَىٰ هَٰذَا غُلَامٌ وَأَسَرُّوهُ بِضَاعَةً وَاللَّهُ عَلِيمٌ بِمَا يَعْمَلُونَ ۝ وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ ۝ وَقَالَ الَّذِي اشْتَرَاهُ مِنْ مِصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَنْ يَنْفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ﴾.\n\n- أ. ما مظاهر لطفه -سبحانه وتعالى- بيوسف -عليه السلام- كما ورد في الآية الأخيرة؟\n- ب. لماذا طلب عزيز مصر من زوجته أن تكرم مثوى سيدنا يوسف؟\n- ج. على مَن تعود (واو الجماعة) في الفعل (شروه)؟\n- د. وصف الله -تعالى- قصّة يوسف بأنها أحسن القصص، علّل ذلك.\nfinal-answer:\n- أ. قيّض الله له مَن يشتريه، (وهو عزيز مصر). عطّف عليه قلب الذي اشتراه، فأوصى زوجته أن تعتني به (فقال لزوجته أكرمي مثواه). مكّن ليوسف في الأرض (مصر)، علّمه تأويل الأحاديث (تفسير الأحاديث).\n- ب. لأنّه لم يكن له ولد، فأراد أن يكون يوسف بمكان ولده، فينتفع به مع زوجته في كبرهما، أو (عسى أن ينفعهما أو يتّخذاه ولدًا).\n- ج. يعود الضمير على إخوة يوسف عليه السلام (على رأي معظم المفسّرين). يعود على القافلة (على رأي بعض المفسّرين).\n- د. وصف الله -سبحانه وتعالى- قصّة يوسف بأنها أحسن القصص لأنّها عالجت مسائل اجتماعية نفسيّة أخلاقيّة، وجاءت متكاملة البناء الدراميّ من أولها إلى آخرها في السورة نفسها، وبدأت برؤيا وانتهت بتحقيق هذه الرؤيا.\nsolution:\nتتتابع مظاهر اللطف الإلهي: النجاة من الجبّ، ثم شراء العزيز له وإكرامه، ثم التمكين وتعليم التأويل. ويبيّن «عسى أن ينفعنا أو نتّخذه ولدًا» سبب إكرام العزيز له. أمّا ضمير «شروه» فتتعدد أقوال التفسير في مرجعه؛ يُحفظ هذا الاختلاف الوارد في الجواب. ويُفسَّر وصف القصة بأحسن القصص بوحدة بنائها وتمام أحداثها وما تعالجه من قيم نفسية واجتماعية وأخلاقية.\n:::\n\n:::exam-question\nid: ar1-e-p008-q01\ntitle: مجموعة الامتحانات · ص 7 · PDF 8 · السؤال 4 · 2021، الدورة الأولى، شهر 6، العلمي\nquestion: اقرأ الآيات الآتية من (سورة يوسف) ثمّ أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 7 · PDF 8 · السؤال 4 · 2021، الدورة الأولى، شهر 6، العلمي\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الآيات الآتية من (سورة يوسف) ثمّ أجب عن الأسئلة التي تليها:\n\nقال تعالى: ﴿نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِمَا أَوْحَيْنَا إِلَيْكَ هَٰذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغَافِلِينَ ۝٣ إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِينَ ۝٤ قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْدًا إِنَّ الشَّيْطَانَ لِلْإِنْسَانِ عَدُوٌّ مُبِينٌ ۝٥﴾.\n\n- أ. وصف الله -عزّ وجلّ- قصّة يوسف (عليه السلام) بأنّها أحسن القصص لعدة أسباب، اذكر اثنتين منها.\n- ب. اذكر سبب نزول هذه السورة على سيّدنا محمد -عليه الصلاة والسلام-.\n- ج. وردت في الآيات السابقة الكلمتان (أحسن، يوسف)، اكتب المعنى الصرفيّ للأولى، وإعراب الثانية.\n- د. علّل: قال يعقوب لابنه يوسف -عليهما السلام-: «لا تقصص رؤياك على إخوتك».\nfinal-answer:\n- أ. عالجت مسائل اجتماعية نفسيّة أخلاقيّة. جاءت متكاملة البناء الدراميّ من أوّلها إلى آخرها في السورة نفسها.\n- ب. لتخفّف عنه ضيق نفسه من أذى قريش / لتظلّ عبرة للمؤمنين جميعهم.\n- ج. الأولى: أحسن: اسم تفضيل. الثانية: يوسف: فاعل مرفوع وعلامة رفعه الضمّة الظاهرة.\n- د. كي لا يكيدوا له حسدًا وغيرة.\nsolution:\nيُستدل لوصف القصة بأحسن القصص بترابط أحداثها وما تحمله من عبر، لا بمجرد جمال العبارة. ويصل نزولها بتثبيت النبي ﷺ أمام أذى قومه. «أحسن» على وزن «أفعل» للمفاضلة فهي اسم تفضيل، و«يوسف» هو الذي قام بالفعل «قال» فهو فاعل مرفوع. وعبارة «فيكيدوا لك كيدًا» تصرّح بسبب النهي عن إخبار الإخوة بالرؤيا.\n:::\n\n:::exam-question\nid: ar1-e-p008-q02\ntitle: مجموعة الامتحانات · ص 7 · PDF 8 · السؤال 5 · 2021\nquestion: اذكر الآراء التي طرحها إخوة يوسف للتخلّص منه.\nreference: مجموعة الامتحانات · ص 7 · PDF 8 · السؤال 5 · 2021\nanswer-label: إجابة المفتاح المرفق\nbody:\nاذكر الآراء التي طرحها إخوة يوسف للتخلّص منه.\nfinal-answer:\n- أ. قتل يوسف (عليه السلام).\n- ب. أن يلقوه في أرض بعيدة.\n- ج. أن يلقوه في الجبّ.\nsolution:\nترد الآراء في الآيتين التاسعة والعاشرة: القتل، والطرح في أرض بعيدة، والإلقاء في غيابة الجبّ. يجمعها سعي الإخوة إلى إبعاد يوسف ليخلص لهم اهتمام أبيهم.\n:::\n\n:::exam-question\nid: ar1-e-p008-q03\ntitle: مجموعة الامتحانات · ص 7 · PDF 8 · السؤال 6 · 2021، الدورة الثالثة، العلمي، شهر 12\nquestion: اقرأ الآيات الآتية من درس (اشتدي أزمة تنفرجي) ثمّ أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 7 · PDF 8 · السؤال 6 · 2021، الدورة الثالثة، العلمي، شهر 12\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الآيات الآتية من درس (اشتدي أزمة تنفرجي) ثمّ أجب عن الأسئلة التي تليها:\n\nقال تعالى: ﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيَابَةِ الْجُبِّ وَأَوْحَيْنَا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ ۝١٥ وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ۝١٦ قَالُوا يَا أَبَانَا إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِنْدَ مَتَاعِنَا فَأَكَلَهُ الذِّئْبُ وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ﴾.\n\n- أ. اكتب رأيين من الآراء المختلفة التي طرحها إخوة يوسف للتخلّص منه.\n- ب. ما الدليل على كذب إخوة يوسف في قوله تعالى على لسانهم: ﴿فأكله الذئب﴾؟\n- ج. ما مرادف (غيابة الجبّ)؟\nfinal-answer:\n- أ. قتل يوسف (عليه السلام)، أن يلقوه في أرض بعيدة، أن يلقوه في الجبّ.\n- ب. الدليل أنّ قميصه سليم لم يتمزّق.\n- ج. الجزء المخفيّ من البئر.\nsolution:\nنستخرج المقترحين من أوامر الإخوة في النص السابق: القتل أو الطرح بعيدًا أو الإلقاء في الجبّ. وادعاء أكل الذئب لا يوافق سلامة القميص من التمزّق. «غيابة الجبّ» موضعه الغائر المستتر عن الأنظار، ولذلك اختاروه لإخفائه.\n:::\n\n:::exam-question\nid: ar1-e-p009-q01\ntitle: مجموعة الامتحانات · ص 8 · PDF 9 · السؤال 7 · 2022، الدورة الأولى، شهر 6\nquestion: اقرأ الآيات الآتية من (سورة يوسف) ثم أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 8 · PDF 9 · السؤال 7 · 2022، الدورة الأولى، شهر 6\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الآيات الآتية من (سورة يوسف) ثم أجب عن الأسئلة التي تليها:\n\nقال تعالى: ﴿وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَنْ يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ ۝٢٥ قَالَ هِيَ رَاوَدَتْنِي عَنْ نَفْسِي وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا إِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ ۝٢٦ وَإِنْ كَانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ ۝٢٧ فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِنْ دُبُرٍ قَالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ <u>عَظِيمٌ</u> ۝٢٨ يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخَاطِئِينَ ۝٢٩﴾.\n\n- أ. بيّن العقوبة التي اقترحت امرأة العزيز إيقاعها بيوسف عليه السلام.\n- ب. نوضّح المقصود بقوله تعالى: «يوسف أعرض عن هذا».\n- ج. وردت في الآيات السابقة الكلمات (ألفيا، كيدكنّ، عظيمٌ) اكتب الجذر اللغوي للأولى، ومرادف الثانية، وإعراب الثالثة.\n- د. ما الحكمة من تنكير كلمة شاهد؟\n- هـ. الحسد آفة اجتماعيّة، اشرح هذه الظاهرة.\nfinal-answer:\n- أ. السجن أو العذاب الأليم.\n- ب. أي اترك ذكر ما كان من امرأة العزيز، ولا تذكره لأحد.\n- ج. الأولى: لفي، الثانية: مكركنّ وحيلكنّ، الثالثة: خبر إنّ مرفوع وعلامة رفعه الضمّة.\n- د. لا أهميّة لشخص الشاهد على وجه الخصوص، وإنّما الأهميّة في الحكم بالقضيّة، بغض النظر عمّن يكون هذا الشاهد.\n- هـ. فمثلًا قد يحسد الطالب زميله الذي تفوّق عليه في التحصيل العلمي، أو في أيّ مجال آخر، فيدفعه حسده إلى الكيد له، والوشاية به لدى معلميه كذبًا وزورًا، أو يحاول تعطيله عن دراسته، بسرقة دفاتره قبل الامتحان مباشرة.\nsolution:\nالعقوبة منصوص عليها في «أن يُسجن أو عذاب أليم»، و«أعرض عن هذا» طلب كتمان الحادثة. «ألفيا» بمعنى وجدا، وجذرها ل ف ي؛ و«كيدكنّ» حيلكنّ ومكركنّ. في «إنّ كيدكنّ عظيم» تمّ الاسم بـ«كيدكنّ»، فـ«عظيم» خبره المرفوع. وتنكير «شاهد» يوجّه الاهتمام إلى حجته لا اسمه. ويُناقش أثر الحسد بالانتقال من تمني زوال النعمة إلى سلوك مؤذٍ، كما قاد حسد الإخوة إلى ظلم يوسف.\n:::\n\n:::exam-question\nid: ar1-e-p009-q02\ntitle: مجموعة الامتحانات · ص 8 · PDF 9 · السؤال 8 · 2022، الدورة الثانية، الضفة، شهر 8\nquestion: اقرأ الآيات الآتية من درس (اشتدي أزمة تنفرجي) ثم أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 8 · PDF 9 · السؤال 8 · 2022، الدورة الثانية، الضفة، شهر 8\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الآيات الآتية من درس (اشتدي أزمة تنفرجي) ثم أجب عن الأسئلة التي تليها:\n\n﴿لَقَدْ كَانَ فِي يُوسُفَ وَإِخْوَتِهِ آيَاتٌ لِلسَّائِلِينَ ۝٧ إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُبِينٍ ۝٨ اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْمًا صَالِحِينَ ۝٩ قَالَ قَائِلٌ مِنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي <u>غَيَابَةِ الْجُبِّ</u> يَلْتَقِطْهُ بَعْضُ <u>السَّيَّارَةِ</u> إِنْ كُنْتُمْ فَاعِلِينَ ۝١٠ قَالُوا يَا أَبَانَا مَا لَكَ لَا تَأْمَنَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُ لَنَاصِحُونَ ۝١١﴾.\n\n- أ. لماذا لا يأمن يعقوب إخوة يوسف عليه؟\n- ب. ما معنى ما تحته خطّ؟\n- ج. ما نوع اللام في قوله: «ليوسف وأخوه»؟\n- د. استخرج من النصّ: اسم فاعل حدث فيه إعلال، واسم إنّ مضافًا، وطباقًا.\n- هـ. ورد في قصّة يوسف ما يوضّح أنّ يوسف من عباد الله الصالحين. نبيّن ذلك.\nfinal-answer:\n- أ. خاف عليه أن يأكله الذئب.\n- ب. غيابة الجبّ: الجزء المخفيّ من البئر. السيّارة: القافلة.\n- ج. لام الابتداء.\n- د. قائل. إنّ أبانا. اقتلوا / لا تقتلوا.\n- هـ. أن الله عزّ وجلّ علّمه تأويل الأحاديث، وأنّ الله عصمه من الوقوع في الفاحشة.\nsolution:\nخوف يعقوب المصرّح به في السياق أن يأكله الذئب، وسبق تحذيره من كيد الإخوة. «غيابة الجبّ» جزء البئر المستتر، و«السيّارة» القافلة. واللام في «ليوسف» للتوكيد وليست حرف جر. اسم الفاعل «قائل» أصله من «قال» وقد أُبدلت عينه همزة، و«أبانا» اسم إنّ وهو مضاف، و«اقتلوا/لا تقتلوا» طباق سلب. ويُستدل على صلاح يوسف بتعليم التأويل وحفظه من الفاحشة.\n:::";

